import { AgentPackSchema, type AgentPack } from "./schema";

export const AGENT_PACK_IDS = ["market-strategist"] as const;
export type AgentPackId = (typeof AGENT_PACK_IDS)[number];

/** Each bundle is generated by scripts/build-agent-pack-bundles.mjs and loaded on demand. */
const bundles: Record<AgentPackId, () => Promise<{ default: unknown }>> = {
  "market-strategist": () => import("./bundles/market-strategist.json"),
};

export async function loadAgentPack(id: AgentPackId): Promise<AgentPack> {
  const bundle = await bundles[id]();
  return AgentPackSchema.parse(bundle.default);
}
